"""Generated byte-response boundaries apply before decoding or another request."""

from __future__ import annotations

import importlib
import io

import pytest


def module():
    try:
        return importlib.import_module(
            "bijux_pollenomics.collection.sources.sead.acquisition.context.transport"
        )
    except ModuleNotFoundError:
        pytest.fail("Bounded unresolved-context byte transport is not implemented")


class Response(io.BytesIO):
    """Generated native-shaped ordinary HTTP response."""

    status = 200
    url = "https://browser.sead.se/postgrest/tbl_sites?select=site_id"

    def __init__(self, body=b"[]"):
        super().__init__(body)
        self.requested = []

    def read(self, size=-1):
        self.requested.append(size)
        assert size > 0
        return super().read(size)


def transport(opener, **kwargs):
    owner = module()
    limits = importlib.import_module(owner.__package__).SeadContextLimits(**kwargs)
    return owner.ContextTransport(opener, limits=limits, clock=lambda: 0.0)


def request(client):
    return client.fetch(
        "https://browser.sead.se/postgrest/tbl_sites",
        params=[("select", "site_id")],
        headers={"Range": "0-99", "Range-Unit": "items"},
        timeout=30.0,
    )


def test_response_closed_and_literal_json_preserved():
    response = Response(b'[{"site_id":2,"unknown":null}]')
    client = transport(lambda *args, **kwargs: response)
    assert request(client) == [{"site_id": 2, "unknown": None}]
    assert response.closed
    assert list(client.responses.values()) == [b'[{"site_id":2,"unknown":null}]']


@pytest.mark.parametrize(
    "body",
    [b'{"not":"array"}', b'[{"id":1,"id":2}]', b"[NaN]", b"[Infinity]", b"[true]"],
)
def test_invalid_or_ambiguous_json_retains_original_response(body):
    response = Response(body)
    client = transport(lambda *args, **kwargs: response)
    with pytest.raises(ValueError):
        request(client)
    assert response.closed
    assert list(client.responses.values()) == [body]


def test_sentinel_bound_precedes_json_decoding():
    response = Response(b"x" * 20)
    client = transport(lambda *args, **kwargs: response, response_bytes=8)
    with pytest.raises(ValueError, match="byte"):
        request(client)
    assert response.closed
    assert sum(response.requested) == 9
    assert client.byte_count == 9


def test_aggregate_exhaustion_prevents_next_opener_call():
    calls = []
    client = transport(lambda *a, **kw: calls.append(kw) or Response(), max_bytes=2)
    assert request(client) == []
    with pytest.raises(ValueError, match="budget"):
        request(client)
    assert len(calls) == 1


def test_request_limit_counts_attempts_without_retry():
    calls = []
    client = transport(lambda *a, **kw: calls.append(kw) or Response(), max_requests=1)
    request(client)
    with pytest.raises(ValueError, match="budget"):
        request(client)
    assert len(calls) == 1


def test_redirected_response_refuses_before_body_read():
    response = Response()
    response.url = "https://foreign.invalid/tbl_sites"
    client = transport(lambda *a, **kw: response)
    with pytest.raises(ValueError, match="redirect"):
        request(client)
    assert response.requested == []
    assert response.closed


def test_read_failure_survives_close_failure():
    primary = OSError("generated primary")

    class Broken(Response):
        def read(self, size=-1):
            raise primary

        def close(self):
            super().close()
            raise RuntimeError("generated secondary")

    response = Broken()
    client = transport(lambda *a, **kw: response)
    with pytest.raises(OSError) as caught:
        request(client)
    assert caught.value is primary
    assert response.closed


def test_wall_budget_is_checked_before_opener():
    owner = module()
    times = iter([0.0, 31.0])
    limits = importlib.import_module(owner.__package__).SeadContextLimits(
        max_seconds=30
    )
    calls = []
    client = owner.ContextTransport(
        lambda *a, **kw: calls.append(kw), limits=limits, clock=lambda: next(times)
    )
    with pytest.raises(ValueError, match="budget"):
        request(client)
    assert calls == []
